using Resolver = void* (*)(const char*);

struct GlApi {
    // Null until load() succeeds. Calling a null slot is not allowed.
    const unsigned char* (STUDY_GL_CALL* GetString)(GLenum)          = nullptr;
    void                 (STUDY_GL_CALL* GetIntegerv)(GLenum, GLint*) = nullptr;
    GLenum               (STUDY_GL_CALL* GetError)(void)             = nullptr;
};

template <typename Fn>
bool resolve_slot(Fn& slot, Resolver resolver, const char* name)
{
    void* raw = resolver(name);
    if (raw == nullptr) {
        // Report this name and keep going, so the caller sees every gap.
        std::fprintf(stderr, "[GL] missing entry point: %s\n", name);
        return false;
    }
    // `Fn` is the value type of the slot. The void* -> function-pointer conversion is the
    // platform (SDL) contract, not a universally portable ISO rule.
    slot = reinterpret_cast<Fn>(raw);
    return true;
}

bool load(GlApi& out, Resolver resolver)
{
    // Clear first: a previous successful load must not survive a new attempt.
    out = GlApi{};

    if (resolver == nullptr) {
        std::fprintf(stderr, "[GL] load called with a null resolver.\n");
        return false;
    }

    // Fill a local candidate. `out` stays cleared unless every slot resolves.
    GlApi candidate;
    bool ok = true;
    ok = resolve_slot(candidate.GetString,   resolver, "glGetString") && ok;
    ok = resolve_slot(candidate.GetIntegerv, resolver, "glGetIntegerv") && ok;
    ok = resolve_slot(candidate.GetError,    resolver, "glGetError") && ok;

    if (!ok) {
        return false; // candidate is discarded; `out` remains cleared.
    }

    out = candidate; // all slots valid: publish at once.
    return true;
}

const auto* version = gl.GetString(study_gl::Version);
const auto* renderer = gl.GetString(study_gl::Renderer);
study_gl::GLint attributes = 0, major = 0, minor = 0, profile = 0;
gl.GetIntegerv(study_gl::MajorVersion, &major);
gl.GetIntegerv(study_gl::MinorVersion, &minor);
gl.GetIntegerv(study_gl::ContextProfileMask, &profile);
gl.GetIntegerv(study_gl::MaxVertexAttribs, &attributes);
const bool version_ok = major > 3 || (major == 3 && minor >= 3);
if (!version || !renderer || gl.GetError() != 0 || !version_ok ||
    !(profile & study_gl::CoreProfileBit)) {
    std::fputs("GL diagnostic query/version/profile failed\n", stderr);
    return 1;
}
std::printf("GL %s | %s | actual=%d.%d core, max attributes=%d\n",
            reinterpret_cast<const char*>(version), reinterpret_cast<const char*>(renderer),
            major, minor, attributes);

int main()
{
    if (!platform_init(640, 480, "Tetris study: GL loader")) return 1;
    const int result = run_session();
    platform_shutdown(); // Failure in loading also reaches this cleanup.
    return result;
}

void* platform_gl_get_proc(const char* name)
{
    if (!active || !name || !*name ||
        SDL_GL_GetCurrentContext() != active->context.get() ||
        SDL_GL_GetCurrentWindow() != active->window.get()) return nullptr;
    return SDL_GL_GetProcAddress(name);
}
